function summarize(text, opts){
  opts=opts||{}; var n=opts.n!=null?opts.n:3; if(n<1)n=1; else if(n>20)n=20;
  var STOP={the:1,a:1,an:1,and:1,or:1,but:1,to:1,of:1,in:1,on:1,for:1,is:1,are:1,was:1,were:1,it:1,this:1,that:1,by:1,as:1,at:1,with:1,from:1,be:1,will:1,can:1,do:1,we:1,you:1,he:1,she:1,they:1,his:1,her:1,its:1,our:1,your:1};
  var sens=text.replace(/\r/g,' ').split(/[.!?。！？]+/).map(function(s){return s.trim();}).filter(Boolean);
  if(sens.length===0) return '';
  var freq={};
  for(var i=0;i<sens.length;i++){ var ws=sens[i].toLowerCase().match(/[a-z0-9一-龥]+/g)||[]; for(var j=0;j<ws.length;j++){ var w=ws[j]; if(!STOP[w]) freq[w]=(freq[w]||0)+1; } }
  var scored=sens.map(function(s,idx){ var ws=s.toLowerCase().match(/[a-z0-9一-龥]+/g)||[]; var sc=0; for(var j=0;j<ws.length;j++){ sc+=(freq[ws[j]]||0); } return {s:s, idx:idx, sc:sc}; });
  scored.sort(function(a,b){ return b.sc-a.sc || a.idx-b.idx; });
  var top=scored.slice(0, Math.min(n, scored.length)).sort(function(a,b){ return a.idx-b.idx; });
  return top.map(function(t){ return t.s; }).join(' ');
}

var EXPORTS={summarize:summarize};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SummarizeForgePure = EXPORTS; }
